sys_relationship.query_with:
(function refineQuery(current, parent) {

	// Add your code here, such as current.addQuery(field, value);
	var users =[];
	var skills = [];
	var gr = new GlideRecord('x_kp101_kpmg_res_0_user_skill');
	gr.addQuery('user', current.resource_name.sys_id);
	//gr.addQuery('skill', parent.sys_id);
	gr.query();
	if(gr.next()){
		users.push(gr.user);
	//	skills.push(gr.skill);
	}

	current.addEncodedQuery("resource_name.sys_idLIKE"+users.toString());


})(current, parent);
